import type { Mock } from "vitest";
import { beforeEach, vi } from "vitest";
import { serveStatic, type ServeStaticOptions, type StaticAssetMeta } from "../src/index.ts";
import { describeMatrix } from "./_setup.ts";

const BODY = "0123456789";
const MTIME = 1_704_067_200_000; // Mon, 01 Jan 2024 00:00:00 GMT
const LAST_MODIFIED = new Date(MTIME).toUTCString();

const encoder = new TextEncoder();

function streamOf(chunks: Uint8Array[]): ReadableStream<Uint8Array> {
  return new ReadableStream({
    start(controller) {
      for (const chunk of chunks) {
        controller.enqueue(chunk);
      }
      controller.close();
    },
  });
}

describeMatrix("serve static range", (t, { it, expect }) => {
  let meta: StaticAssetMeta | undefined;
  let getContents: Mock<ServeStaticOptions["getContents"]>;
  let options: ServeStaticOptions;

  beforeEach(() => {
    meta = { type: "text/plain", etag: '"v1"', mtime: MTIME, size: 10 };
    getContents = vi.fn(() => BODY);
    options = { getMeta: () => meta, getContents };
    t.app.all("/**", (event) => serveStatic(event, options));
  });

  const bytes = async (res: Response) => new Uint8Array(await res.arrayBuffer());

