  it("announces accept-ranges and serves the full asset on GET without Range", async () => {
    const res = await t.fetch("/file.txt");

    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(await res.text()).toBe(BODY);
  });

  // RF-02
  it("responds 206 with the requested bytes on GET", async () => {
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=2-4" } });

    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 2-4/10");
    expect(res.headers.get("content-length")).toBe("3");
    expect(await res.text()).toBe("234");
