import type { Mock } from "vitest";
import { beforeEach, vi } from "vitest";
import { serveStatic, type ServeStaticOptions, type StaticAssetMeta } from "../src/index.ts";
import { describeMatrix } from "./_setup.ts";

const BODY = "0123456789";
const MTIME = 1_704_067_200_000; // Mon, 01 Jan 2024 00:00:00 GMT
const LAST_MODIFIED = new Date(MTIME).toUTCString();

const encoder = new TextEncoder();

function streamOf(chunks: Uint8Array[]): ReadableStream<Uint8Array> {
  return new ReadableStream({
    start(controller) {
      for (const chunk of chunks) {
        controller.enqueue(chunk);
      }
      controller.close();
    },
  });
}

describeMatrix("serve static range", (t, { it, expect }) => {
  let meta: StaticAssetMeta | undefined;
  let getContents: Mock<ServeStaticOptions["getContents"]>;
  let options: ServeStaticOptions;

  beforeEach(() => {
    meta = { type: "text/plain", etag: '"v1"', mtime: MTIME, size: 10 };
    getContents = vi.fn(() => BODY);
    options = { getMeta: () => meta, getContents };
    t.app.all("/**", (event) => serveStatic(event, options));
  });

  const bytes = async (res: Response) => new Uint8Array(await res.arrayBuffer());

  // RF-01
  it("announces accept-ranges and serves the full asset on GET without Range", async () => {
    const res = await t.fetch("/file.txt");

    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(await res.text()).toBe(BODY);
  });

  // RF-02
  it("responds 206 with the requested bytes on GET", async () => {
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=2-4" } });

    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 2-4/10");
    expect(res.headers.get("content-length")).toBe("3");
    expect(await res.text()).toBe("234");
  });

  // RF-02
  it("responds 206 without a body on HEAD and does not call getContents", async () => {
    const res = await t.fetch("/file.txt", { method: "HEAD", headers: { range: "bytes=2-4" } });

    expect(res.status).toBe(206);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(res.headers.get("content-range")).toBe("bytes 2-4/10");
    expect(res.headers.get("content-length")).toBe("3");
    expect(await res.text()).toBe("");
    expect(getContents).not.toHaveBeenCalled();
  });

  // RF-03
  it("clamps end, suffix and oversized suffix ranges", async () => {
    const cases: [string, string][] = [
      ["bytes=7-100", "bytes 7-9/10"],
      ["bytes=-3", "bytes 7-9/10"],
      ["bytes=-50", "bytes 0-9/10"],
    ];
    for (const [range, contentRange] of cases) {
      const res = await t.fetch("/file.txt", { headers: { range } });
      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe(contentRange);
    }
  });

  // RF-03
  it("serves an open-ended range from the start to the end", async () => {
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=2-" } });

    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 2-9/10");
    expect(res.headers.get("content-length")).toBe("8");
    expect(await res.text()).toBe("23456789");
  });

  // RF-04
  it("responds 416 with an unsatisfiable range and does not call getContents", async () => {
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=10-20" } });

    expect(res.status).toBe(416);
    expect(res.headers.get("content-range")).toBe("bytes */10");
    expect(res.headers.get("content-length")).toBe("0");
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(await res.text()).toBe("");
    expect(getContents).not.toHaveBeenCalled();
  });

  // RF-04
  it("responds 416 for a zero-length suffix", async () => {
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=-0" } });

    expect(res.status).toBe(416);
    expect(res.headers.get("content-range")).toBe("bytes */10");
  });

  // RF-05
  const ignoredRanges = [
    "items=0-1",
    "bytes=0-1,4-5",
    "bytes=abc",
    "bytes=",
    "bytes=1",
    "bytes=-",
    "bytes=5-2",
  ];
  for (const range of ignoredRanges) {
    it(`ignores Range "${range}" and serves the full asset`, async () => {
      const res = await t.fetch("/file.txt", { headers: { range } });

      expect(res.status).toBe(200);
      expect(res.headers.has("content-range")).toBe(false);
      expect(res.headers.get("accept-ranges")).toBe("bytes");
      expect(await res.text()).toBe(BODY);
    });
  }

  // RF-05
  it("tolerates spaces around the unit, the equal sign and the numbers", async () => {
    for (const range of ["bytes = 2 - 4", "  bytes=2-4  "]) {
      const res = await t.fetch("/file.txt", { headers: { range } });

      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe("bytes 2-4/10");
    }
  });

  // RF-06
  it("honors Range when If-Range matches the strong ETag", async () => {
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=2-4", "if-range": '"v1"' },
    });

    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 2-4/10");
  });

  // RF-06
  it("ignores Range when If-Range is a weak ETag", async () => {
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=2-4", "if-range": 'W/"v1"' },
    });

    expect(res.status).toBe(200);
    expect(res.headers.has("content-range")).toBe(false);
    expect(await res.text()).toBe(BODY);
  });

  // RF-06
  it("ignores Range when the asset ETag is weak, even if If-Range matches", async () => {
    meta = { ...meta, etag: 'W/"v1"' };
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=2-4", "if-range": '"v1"' },
    });

    expect(res.status).toBe(200);
    expect(res.headers.has("content-range")).toBe(false);
    expect(await res.text()).toBe(BODY);
  });

  // RF-06
  it("honors Range when If-Range is exactly the last-modified date", async () => {
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=2-4", "if-range": LAST_MODIFIED },
    });

    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 2-4/10");
  });

  // RF-06
  it("ignores Range when If-Range is a different date", async () => {
    const res = await t.fetch("/file.txt", {
      headers: {
        range: "bytes=2-4",
        "if-range": new Date(MTIME + 1000).toUTCString(),
      },
    });

    expect(res.status).toBe(200);
    expect(res.headers.has("content-range")).toBe(false);
  });

  // RF-06
  it("ignores Range when If-Range is a date and the asset has no last-modified", async () => {
    meta = { ...meta, mtime: undefined };
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=2-4", "if-range": LAST_MODIFIED },
    });

    expect(res.status).toBe(200);
    expect(res.headers.has("content-range")).toBe(false);
    expect(res.headers.has("last-modified")).toBe(false);
  });

  // RF-06
  it("ignores If-Range when there is no Range", async () => {
    const res = await t.fetch("/file.txt", { headers: { "if-range": '"v1"' } });

    expect(res.status).toBe(200);
    expect(res.headers.has("content-range")).toBe(false);
    expect(await res.text()).toBe(BODY);
  });

  // RF-06
  it("ignores a false If-Range before an unsatisfiable range, so it is not 416", async () => {
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=10-20", "if-range": 'W/"v1"' },
    });

    expect(res.status).toBe(200);
    expect(res.headers.has("content-range")).toBe(false);
  });

  // RF-07
  it("responds 304 before evaluating Range when If-None-Match matches", async () => {
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=0-3", "if-none-match": '"v1"' },
    });

    expect(res.status).toBe(304);
    expect(res.headers.has("content-range")).toBe(false);
    expect(await res.text()).toBe("");
    expect(getContents).not.toHaveBeenCalled();
  });

  // RF-07
  it("responds 304 before evaluating Range when If-Modified-Since matches", async () => {
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=0-3", "if-modified-since": LAST_MODIFIED },
    });

    expect(res.status).toBe(304);
    expect(res.headers.has("content-range")).toBe(false);
    expect(getContents).not.toHaveBeenCalled();
  });

  // RF-08
  const unknownSizes: [string, number | undefined][] = [
    ["missing", undefined],
    ["a string", "10" as unknown as number],
    ["NaN", Number.NaN],
  ];
  for (const [label, size] of unknownSizes) {
    it(`ignores Range and accept-ranges when size is ${label}`, async () => {
      meta = { ...meta, size };
      const res = await t.fetch("/file.txt", { headers: { range: "bytes=0-3" } });

      expect(res.status).toBe(200);
      expect(res.headers.has("accept-ranges")).toBe(false);
      expect(res.headers.has("content-range")).toBe(false);
    });
  }

  // RF-09
  it("applies Range to the selected encoded variant", async () => {
    options.encodings = { gzip: ".gz" };
    options.getMeta = (id) =>
      id === "/app.js.gz"
        ? { type: "text/javascript", encoding: "gzip", size: 6 }
        : id === "/app.js"
          ? { type: "text/javascript", size: 10 }
          : undefined;
    options.getContents = (id) => (id === "/app.js.gz" ? "abcdef" : BODY);

    const res = await t.fetch("/app.js", {
      headers: { "accept-encoding": "gzip", range: "bytes=0-1" },
    });

    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-1/6");
    expect(res.headers.get("content-encoding")).toBe("gzip");
    expect(await res.text()).toBe("ab");
  });

  // RF-09
  it("keeps the encoded variant headers on 416", async () => {
    options.encodings = { gzip: ".gz" };
    options.getMeta = (id) =>
      id === "/app.js.gz"
        ? { type: "text/javascript", encoding: "gzip", size: 6 }
        : id === "/app.js"
          ? { type: "text/javascript", size: 10 }
          : undefined;

    const res = await t.fetch("/app.js", {
      headers: { "accept-encoding": "gzip", range: "bytes=10-20" },
    });

    expect(res.status).toBe(416);
    expect(res.headers.get("content-encoding")).toBe("gzip");
    expect(res.headers.get("content-range")).toBe("bytes */6");
  });

  // RF-10
  it("slices a ReadableStream body delivered in two chunks", async () => {
    getContents.mockImplementation(() =>
      streamOf([encoder.encode("01234"), encoder.encode("56789")]),
    );

    const res = await t.fetch("/file.txt", { headers: { range: "bytes=3-6" } });

    expect(res.status).toBe(206);
    expect(await res.text()).toBe("3456");
  });

  // RF-10
  const bodies: [string, () => BodyInit][] = [
    ["string", () => BODY],
    ["Blob", () => new Blob([BODY])],
    ["ArrayBuffer", () => encoder.encode(BODY).buffer as ArrayBuffer],
    ["Uint8Array", () => encoder.encode(BODY)],
    ["ReadableStream", () => streamOf([encoder.encode(BODY)])],
  ];
  for (const [name, makeBody] of bodies) {
    it(`returns the same bytes as the 200 response for a ${name} body`, async () => {
      getContents.mockImplementation(makeBody);

      const full = await bytes(await t.fetch("/file.txt"));
      const partial = await t.fetch("/file.txt", { headers: { range: "bytes=3-6" } });

      expect(partial.status).toBe(206);
      expect(await bytes(partial)).toEqual(full.slice(3, 7));
    });
  }

  // D-07 / R2
  for (const value of [null, undefined]) {
    it(`responds 200 without content-range when getContents returns ${value}`, async () => {
      getContents.mockImplementation(() => value);
      const res = await t.fetch("/file.txt", { headers: { range: "bytes=2-4" } });

      expect(res.status).toBe(200);
      expect(res.headers.has("content-range")).toBe(false);
      expect(await res.text()).toBe("");
    });
  }

  // RF-11
  it("keeps the 405 for non-GET methods even with Range", async () => {
    options.headers = { "cache-control": "public, max-age=60" };
    const res = await t.fetch("/file.txt", {
      method: "DELETE",
      headers: { range: "bytes=0-1" },
    });

    expect(res.status).toBe(405);
    expect(res.headers.get("allow")).toBe("GET, HEAD");
    expect(res.headers.has("content-range")).toBe(false);
    expect(res.headers.has("accept-ranges")).toBe(false);
  });

  // RF-11
  it("keeps the 404 for a missing asset even with Range", async () => {
    meta = undefined;
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=0-1" } });

    expect(res.status).toBe(404);
    expect(res.headers.has("accept-ranges")).toBe(false);
  });

  // RF-11
  it("falls through a missing asset with Range the same way as without it", async () => {
    meta = undefined;
    options.fallthrough = true;
    t.app.all("/**", () => "fallback");

    const plain = await t.fetch("/file.txt");
    const ranged = await t.fetch("/file.txt", { headers: { range: "bytes=0-1" } });

    expect(ranged.status).toBe(plain.status);
    expect(await ranged.text()).toBe(await plain.text());
    expect(ranged.headers.has("accept-ranges")).toBe(false);
  });

  // RF-11
  it("does not serve a non-canonical path with Range", async () => {
    const path = "/pub/%252e%252e/file.txt";
    const plain = await t.fetch(path);
    const ranged = await t.fetch(path, { headers: { range: "bytes=0-1" } });

    expect(plain.status).toBe(404);
    expect(ranged.status).toBe(plain.status);
    expect(ranged.headers.has("content-range")).toBe(false);
  });

  // RF-11 / D-03
  it("keeps an accept-ranges value set in options.headers", async () => {
    options.headers = { "accept-ranges": "none" };
    const res = await t.fetch("/file.txt");

    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBe("none");
  });

  // P4 / D-04
  it("overrides content-length from options.headers on 206", async () => {
    options.headers = { "content-length": "999" };
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=0-1" } });

    expect(res.status).toBe(206);
    expect(res.headers.get("content-length")).toBe("2");
  });

  // RF-04
  it("responds 416 with accept-ranges for an empty asset", async () => {
    meta = { ...meta, size: 0 };
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=0-" } });

    expect(res.status).toBe(416);
    expect(res.headers.get("content-range")).toBe("bytes */0");
    expect(res.headers.get("accept-ranges")).toBe("bytes");
  });

  // RF-01
  for (const method of ["GET", "HEAD"]) {
    const statuses: [number, Record<string, string>][] = [
      [200, {}],
      [206, { range: "bytes=0-1" }],
      [304, { "if-none-match": '"v1"' }],
      [416, { range: "bytes=10-20" }],
    ];
    for (const [status, headers] of statuses) {
      it(`sends accept-ranges on ${method} with status ${status}`, async () => {
