    "bytes=0-1,4-5",
    "bytes=abc",
    "bytes=",
    "bytes=1",
    "bytes=-",
    "bytes=5-2",
  ];
  for (const range of ignoredRanges) {
    it(`ignores Range "${range}" and serves the full asset`, async () => {
