  it("ignores Range when If-Range is a date and the asset has no last-modified", async () => {
    meta = { ...meta, mtime: undefined };
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=2-4", "if-range": LAST_MODIFIED },
    });

    expect(res.status).toBe(200);
    expect(res.headers.has("content-range")).toBe(false);
    expect(res.headers.has("last-modified")).toBe(false);
  });

  // RF-06
  it("ignores If-Range when there is no Range", async () => {
    const res = await t.fetch("/file.txt", { headers: { "if-range": '"v1"' } });

    expect(res.status).toBe(200);
    expect(res.headers.has("content-range")).toBe(false);
    expect(await res.text()).toBe(BODY);
  });

  // RF-06
  it("ignores a false If-Range before an unsatisfiable range, so it is not 416", async () => {
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=10-20", "if-range": 'W/"v1"' },
    });

    expect(res.status).toBe(200);
    expect(res.headers.has("content-range")).toBe(false);
  });

  // RF-07
  it("responds 304 before evaluating Range when If-None-Match matches", async () => {
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=0-3", "if-none-match": '"v1"' },
